#include <iostream>
#include <queue>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::queue<int> waiting;
    for (int i = 0; i < n; i++) {
        int value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        waiting.push(value);
    }
    int k = 0;
    if (!(std::cin >> k)) return 1;
    if (k < 0 || k >= n) return 1;
    for (int i = 0; i < k; i++) {
        waiting.pop();
    }
    std::cout << waiting.front() << std::endl;
    return 0;
}
